trait Db { fn get(&self, k: i64) -> i64; }
struct Db0 { s0: i64, s1: i64 }
impl Db for Db0 { #[inline] fn get(&self, k: i64) -> i64 { let (s0, s1) = (self.s0, self.s1); ((k * s0 + 3) * s1 + 4) } }
struct Db1 { s0: i64, s1: i64 }
impl Db for Db1 { #[inline] fn get(&self, k: i64) -> i64 { let (s0, s1) = (self.s0, self.s1); ((k + s1 * 4) * s0 + 5) } }
struct Db2 { s0: i64, s1: i64 }
impl Db for Db2 { #[inline] fn get(&self, k: i64) -> i64 { let (s0, s1) = (self.s0, self.s1); ((k * 5 - s0) * s1 + 6) } }
struct Db3 { s0: i64, s1: i64 }
impl Db for Db3 { #[inline] fn get(&self, k: i64) -> i64 { let (s0, s1) = (self.s0, self.s1); (((k + 6) * s1) * s0 + 7) } }
