fn pick(seed: i64) -> i64 {
    let mut s = seed;
    for _ in 0..1000 {
        s = lcg(s);
    }
    bits(s)
}

fn keys() -> Vec<i64> {
    (0..1024).map(|i| i * 7919 % 1024).collect()
}

fn hot_dyn(db: &dyn Db, keys: &[i64], n: i64) -> i64 {
    let mut acc = 0;
    for i in 0..n {
        acc += db.get(keys[(i % 1024) as usize]);
    }
    acc
}

fn db_dyn(rounds: i64, calls: i64) -> i64 {
    let dbs: Vec<Box<dyn Db>> = vec![Box::new(Db0 { s0: 2, s1: 3 }), Box::new(Db1 { s0: 3, s1: 6 }), Box::new(Db2 { s0: 4, s1: 9 }), Box::new(Db3 { s0: 5, s1: 5 })];
    hot_dyn(dbs[(pick(rounds) % 4) as usize].as_ref(), &keys(), calls)
}

fn hot_enum(db: &DbE, keys: &[i64], n: i64) -> i64 {
    let mut acc = 0;
    for i in 0..n {
        acc += db.get(keys[(i % 1024) as usize]);
    }
    acc
}

fn db_enum(rounds: i64, calls: i64) -> i64 {
    let dbs: Vec<DbE> = vec![DbE::D0 { s0: 2, s1: 3 }, DbE::D1 { s0: 3, s1: 6 }, DbE::D2 { s0: 4, s1: 9 }, DbE::D3 { s0: 5, s1: 5 }];
    hot_enum(&dbs[(pick(rounds) % 4) as usize], &keys(), calls)
}

