fn stream(n: i64) -> (Vec<usize>, Vec<i64>) {
    let mut which = Vec::with_capacity(n as usize);
    let mut reqs = Vec::with_capacity(n as usize);
    let mut s: i64 = 50;
    for _ in 0..n {
        s = lcg(s);
        let r = bits(s);
        which.push((r % 50) as usize);
        reqs.push((r >> 8) & 1048575);
    }
    (which, reqs)
}

