struct Rng { s: i64 }
impl Rng {
    fn next(&mut self) -> i64 {
        self.s = lcg(self.s);
        bits(self.s)
    }
}

trait Node { fn eval(&self, env: &[i64]) -> i64; }
struct Lit(i64);
struct Slot(usize);
struct Add(Box<dyn Node>, Box<dyn Node>);
struct Sub(Box<dyn Node>, Box<dyn Node>);
struct Lt(Box<dyn Node>, Box<dyn Node>);
struct Neg(Box<dyn Node>);
struct Max(Box<dyn Node>, Box<dyn Node>);
struct Min(Box<dyn Node>, Box<dyn Node>);
impl Node for Lit { fn eval(&self, _: &[i64]) -> i64 { self.0 } }
impl Node for Slot { fn eval(&self, env: &[i64]) -> i64 { env[self.0] } }
impl Node for Add { fn eval(&self, env: &[i64]) -> i64 { self.0.eval(env) + self.1.eval(env) } }
impl Node for Sub { fn eval(&self, env: &[i64]) -> i64 { self.0.eval(env) - self.1.eval(env) } }
impl Node for Lt { fn eval(&self, env: &[i64]) -> i64 { if self.0.eval(env) < self.1.eval(env) { 1 } else { 0 } } }
impl Node for Neg { fn eval(&self, env: &[i64]) -> i64 { -self.0.eval(env) } }
impl Node for Max { fn eval(&self, env: &[i64]) -> i64 { let x = self.0.eval(env); let y = self.1.eval(env); if x > y { x } else { y } } }
impl Node for Min { fn eval(&self, env: &[i64]) -> i64 { let x = self.0.eval(env); let y = self.1.eval(env); if x < y { x } else { y } } }

fn tree_dyn(g: &mut Rng, d: i64) -> Box<dyn Node> {
    let r = g.next();
    if d == 0 || r % 4 == 0 {
        let r2 = g.next();
        if r2 % 2 == 0 { Box::new(Lit(r2 / 2 % 100)) } else { Box::new(Slot((r2 / 2 % 4) as usize)) }
    } else {
        let k = (r >> 8) % 6;
        if k == 3 {
            Box::new(Neg(tree_dyn(g, d - 1)))
        } else {
            let a = tree_dyn(g, d - 1);
            let b = tree_dyn(g, d - 1);
            match k {
                0 => Box::new(Add(a, b)),
                1 => Box::new(Sub(a, b)),
                2 => Box::new(Lt(a, b)),
                4 => Box::new(Max(a, b)),
                _ => Box::new(Min(a, b)),
            }
        }
    }
}

enum Expr {
    Lit(i64),
    Slot(usize),
    Add(Box<Expr>, Box<Expr>),
    Sub(Box<Expr>, Box<Expr>),
    Lt(Box<Expr>, Box<Expr>),
    Neg(Box<Expr>),
    Max(Box<Expr>, Box<Expr>),
    Min(Box<Expr>, Box<Expr>),
}

fn eval(e: &Expr, env: &[i64]) -> i64 {
    match e {
        Expr::Lit(v) => *v,
        Expr::Slot(i) => env[*i],
        Expr::Add(a, b) => eval(a, env) + eval(b, env),
        Expr::Sub(a, b) => eval(a, env) - eval(b, env),
        Expr::Lt(a, b) => if eval(a, env) < eval(b, env) { 1 } else { 0 },
        Expr::Neg(a) => -eval(a, env),
        Expr::Max(a, b) => { let x = eval(a, env); let y = eval(b, env); if x > y { x } else { y } }
        Expr::Min(a, b) => { let x = eval(a, env); let y = eval(b, env); if x < y { x } else { y } }
    }
}

fn tree_enum(g: &mut Rng, d: i64) -> Expr {
    let r = g.next();
    if d == 0 || r % 4 == 0 {
        let r2 = g.next();
        if r2 % 2 == 0 { Expr::Lit(r2 / 2 % 100) } else { Expr::Slot((r2 / 2 % 4) as usize) }
    } else {
        let k = (r >> 8) % 6;
        if k == 3 {
            Expr::Neg(Box::new(tree_enum(g, d - 1)))
        } else {
            let a = Box::new(tree_enum(g, d - 1));
            let b = Box::new(tree_enum(g, d - 1));
            match k {
                0 => Expr::Add(a, b),
                1 => Expr::Sub(a, b),
                2 => Expr::Lt(a, b),
                4 => Expr::Max(a, b),
                _ => Expr::Min(a, b),
            }
        }
    }
}

fn interp_dyn(evals: i64) -> i64 {
    let t = tree_dyn(&mut Rng { s: 1 }, 17);
    let mut total = 0;
    for e in 0..evals {
        let env = [e, e * 3 + 1, e % 7, 100 - e];
        total += t.eval(&env);
    }
    total
}

fn interp_enum(evals: i64) -> i64 {
    let t = tree_enum(&mut Rng { s: 1 }, 17);
    let mut total = 0;
    for e in 0..evals {
        let env = [e, e * 3 + 1, e % 7, 100 - e];
        total += eval(&t, &env);
    }
    total
}


fn main() {
    let args: Vec<String> = env::args().collect();
    let rounds: i64 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(100);
    let kernel = args.get(2).map(|s| s.as_str()).unwrap_or("all");
    let variant = args.get(3).map(|s| s.as_str()).unwrap_or("dyn");
    let n: i64 = if rounds >= 100 { 65536 } else { 1000 };
    let _ = n;
    let run = |k: &str, v: &str| -> i64 {
        match (k, v) {
            ("shapes2", "dyn") => shapes2_dyn(n, rounds),
            ("shapes2", "enum") => shapes2_enum(n, rounds),
            ("shapes4", "dyn") => shapes4_dyn(n, rounds),
            ("shapes4", "enum") => shapes4_enum(n, rounds),
            ("shapes8", "dyn") => shapes8_dyn(n, rounds),
            ("shapes8", "enum") => shapes8_enum(n, rounds),
            ("shapes32", "dyn") => shapes32_dyn(n, rounds),
            ("shapes32", "enum") => shapes32_enum(n, rounds),
            ("db", "dyn") => db_dyn(rounds, n * rounds * 16),
            ("db", "enum") => db_enum(rounds, n * rounds * 16),
            ("router", "dyn") => router_dyn(n, rounds),
            ("router", "enum") => router_enum(n, rounds),
            ("interp", "dyn") => interp_dyn(rounds * (n / 256)),
            ("interp", "enum") => interp_enum(rounds * (n / 256)),
            _ => panic!("no kernel {} {}", k, v),
        }
    };
    if kernel == "all" {
        for k in ["shapes2", "shapes4", "shapes8", "shapes32", "db", "router", "interp"] {
            let a = run(k, "dyn");
            let b = run(k, "enum");
            assert_eq!(a, b, "{}: dyn and enum disagree", k);
            println!("{}", a);
        }
    } else {
        println!("{}", run(kernel, variant));
    }
}
